-- =====================================================================
-- PSP settlement engine and reconciliation (breaks, bank statements)
-- GENERATED by tools/codegen/gen_ddl.py from settlement.spec, recon.spec
-- (same specs as the JPA entities). Edit the spec, regenerate, never hand-edit.
-- =====================================================================

-- A set of payouts to merchants, approved as a unit by someone other than its creator.
CREATE TABLE psp_settlement_batches (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    batch_ref                    VARCHAR(40) NOT NULL,
    currency                     VARCHAR(3) NOT NULL,
    status                       VARCHAR(20) NOT NULL,
    cash_account                 VARCHAR(60) NOT NULL,
    cutoff_at                    DATETIME(6) NOT NULL,
    instruction_count            INT NOT NULL DEFAULT 0,
    total_minor                  BIGINT NOT NULL DEFAULT 0,
    created_by                   VARCHAR(120) NOT NULL,
    submitted_by                 VARCHAR(120),
    submitted_at                 DATETIME(6),
    approved_by                  VARCHAR(120),
    approved_at                  DATETIME(6),
    exported_file_sha256         VARCHAR(64),
    exported_at                  DATETIME(6),
    exported_by                  VARCHAR(120),
    completed_at                 DATETIME(6),
    notes                        VARCHAR(1000),
    created_at                   DATETIME(6) NOT NULL,
    updated_at                   DATETIME(6) NOT NULL,
    version                      BIGINT NOT NULL DEFAULT 0,
    CONSTRAINT uq_settlement_batches_batch_ref UNIQUE (batch_ref),
    INDEX idx_sbatch_status (status,created_at)
);

-- One payout to one merchant. Funds are earmarked in the ledger (SETTLEMENT_PAYABLE) the moment it is created.
CREATE TABLE psp_settlement_instructions (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    instruction_ref              VARCHAR(40) NOT NULL,
    batch_id                     BIGINT NOT NULL,
    merchant_id                  BIGINT NOT NULL,
    currency                     VARCHAR(3) NOT NULL,
    amount_minor                 BIGINT NOT NULL DEFAULT 0,
    payout_account_ref           VARCHAR(40) NOT NULL,
    method                       VARCHAR(20) NOT NULL,
    rail                         VARCHAR(20),
    destination_name             VARCHAR(200) NOT NULL,
    destination_masked           VARCHAR(40) NOT NULL,
    bank_name                    VARCHAR(120),
    status                       VARCHAR(20) NOT NULL,
    reservation_entry_ref        VARCHAR(40),
    paid_entry_ref               VARCHAR(40),
    reversal_entry_ref           VARCHAR(40),
    rail_reference               VARCHAR(150),
    payout_reference             VARCHAR(150),
    proof_sha256                 VARCHAR(64),
    proof_file_name              VARCHAR(255),
    proof_storage_path           VARCHAR(500),
    bank_charge_minor            BIGINT NOT NULL DEFAULT 0,
    failure_reason               VARCHAR(1000),
    sent_at                      DATETIME(6),
    paid_at                      DATETIME(6),
    failed_at                    DATETIME(6),
    confirmed_by                 VARCHAR(120),
    created_at                   DATETIME(6) NOT NULL,
    updated_at                   DATETIME(6) NOT NULL,
    version                      BIGINT NOT NULL DEFAULT 0,
    CONSTRAINT uq_settlement_instructions_instruction_ref UNIQUE (instruction_ref),
    INDEX idx_sinst_batch (batch_id),
    INDEX idx_sinst_merchant (merchant_id,created_at),
    INDEX idx_sinst_status (status)
);

-- A discrepancy needing a human: records never silently corrected. Unique per (source, type, reference); repeats increment occurrences.
CREATE TABLE psp_recon_breaks (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    break_ref                    VARCHAR(40) NOT NULL,
    source                       VARCHAR(40) NOT NULL,
    break_type                   VARCHAR(60) NOT NULL,
    reference                    VARCHAR(150) NOT NULL,
    currency                     VARCHAR(3),
    expected_minor               BIGINT,
    actual_minor                 BIGINT,
    details                      TEXT,
    status                       VARCHAR(20) NOT NULL,
    occurrences                  INT NOT NULL DEFAULT 0,
    first_seen_at                DATETIME(6) NOT NULL,
    last_seen_at                 DATETIME(6) NOT NULL,
    assigned_to                  VARCHAR(120),
    resolution                   VARCHAR(30),
    resolution_note              VARCHAR(2000),
    resolved_by                  VARCHAR(120),
    resolved_at                  DATETIME(6),
    resolution_entry_ref         VARCHAR(40),
    version                      BIGINT NOT NULL DEFAULT 0,
    CONSTRAINT uq_recon_breaks_break_ref UNIQUE (break_ref),
    CONSTRAINT uq_break_key UNIQUE (source,break_type,reference),
    INDEX idx_break_status (status,last_seen_at)
);

-- One line of a trust / settlement bank account statement, imported for reconciliation.
CREATE TABLE psp_bank_statement_lines (
    id                           BIGINT AUTO_INCREMENT PRIMARY KEY,
    import_ref                   VARCHAR(40) NOT NULL,
    cash_account                 VARCHAR(60) NOT NULL,
    currency                     VARCHAR(3) NOT NULL,
    value_date                   DATE NOT NULL,
    bank_reference               VARCHAR(150),
    narrative                    VARCHAR(500),
    direction                    VARCHAR(6) NOT NULL,
    amount_minor                 BIGINT NOT NULL DEFAULT 0,
    running_balance_minor        BIGINT,
    line_hash                    VARCHAR(64) NOT NULL,
    match_status                 VARCHAR(20) NOT NULL,
    matched_type                 VARCHAR(40),
    matched_ref                  VARCHAR(150),
    matched_by                   VARCHAR(120),
    matched_at                   DATETIME(6),
    created_at                   DATETIME(6) NOT NULL,
    CONSTRAINT uq_bank_line UNIQUE (cash_account,line_hash),
    INDEX idx_bank_line_match (match_status,value_date)
);
